// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzzed params: deposit amount and an attacker key to derive an EOA address
    function testFuzz_property(uint128 depositAmount, uint256 attackerKey) public {
        // keep deposit reasonable but wide
        uint256 amount = bound(uint256(depositAmount), 1, 1 ether);

        // deploy attacker helper that will re-enter exactly once
        Attacker attacker = new Attacker(c);

        // fund attacker so it can call addToBalance and receive funds
        address attackerAddr = address(attacker);
        vm.deal(attackerAddr, amount + 1 ether);

        // attacker deposits amount into c
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();

        // verify deposit recorded
        uint256 before = c.getBalance(attackerAddr);
        assertTrue(before == amount);

        // Now attacker will call withdrawBalance(), and in its receive() it will re-enter
        // which should be prevented by the reference (balance zero during call) but exploited by mutant
        bool ok;
        vm.prank(attackerAddr);
        try attacker.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): after withdrawBalance completes, getBalance(attacker) == 0
        // Reference contract: always true. Mutant with external call before zeroing and reentrancy: can be false.
        assertTrue(c.getBalance(attackerAddr) == 0);
    }
}

// Adversarial helper: on receive it will re-enter c.withdrawBalance exactly once to exploit ordering
contract Attacker {
    Reentrance immutable target;
    bool private entered;

    constructor(Reentrance _t) {
        target = _t;
    }

    // allow contract to receive ETH from target.withdrawBalance
    receive() external payable {
        // re-enter exactly once
        if (!entered) {
            entered = true;
            // re-entering withdrawBalance: if target zeroes after external call (mutant), this will withdraw again
            target.withdrawBalance();
        }
    }

    // helper to initiate the withdraw from this contract
    function triggerWithdraw() external {
        target.withdrawBalance();
    }
}
